const frenchIndustryArticle=c=>({
  category:c.category||"Economy of divided France",
  infoboxKicker:c.infoboxKicker||"Industrial history",
  ...c,
  sources:[...frenchIndustrySources,...(c.additionalSources||[])],
  categories:c.categories||[c.category||"Economy of divided France","Northern France","Occitania","Industrial history"]
});

Object.assign(window.deepArticles,{
  "french-industrial-partition-1947":frenchIndustryArticle({
    title:"French industrial partition of 1947",eyebrow:"Lisbon settlement · factories, firms, and technical systems divided",infoboxKicker:"Economic consequence of the French partition",
    lead:"The <strong>French industrial partition of 1947</strong> divided the productive geography of metropolitan France among <a href='northern-france.html'>Northern France</a>, <a href='occitania.html'>Occitania</a>, <a href='brittany.html'>Brittany</a>, territories annexed by Germany, and the German protectorate in Belgium. The settlement transferred immediate control of factories with the territory beneath them but did not automatically settle ownership of shares, patents, brands, debts, pensions, or sales organizations. Industrial France therefore survived as both several national systems and a thicket of unresolved private claims.",
    canon:"The territorial division, northern integration into German standards and finance, Occitania's smaller high-value technical system, and the existence of cross-frontier corporate disputes are established. Plant-level control following the 1947 frontier is the working rule used by this article cluster. Exact confiscation decrees, valuations, compensation schedules, company boards, and final ownership settlements remain open unless separately stated.",
    sections:[
      {id:"geography",title:"The industrial geography inherited in 1947",html:"<p>Paris and the Seine valley held corporate offices, automobile works, electrical plants, laboratories, and skilled subcontractors. Sochaux anchored Peugeot near the German frontier. Lyon and the Rhône corridor held chemicals, pharmaceuticals, machinery, and vehicle production. Clermont-Ferrand centered Michelin, while Toulouse and Bordeaux contained much of the southern aircraft plant and design system.</p>"},
      {id:"rule",title:"Factory control followed territory",html:"<p>The practical rule of partition was possession: the successor government that held a plant licensed its operation, guarded its machinery, allocated power and transport, and approved its management. A shareholder abroad could retain a legal claim without exercising day-to-day control.</p>"},
      {id:"north",title:"Northern France and continental integration",html:"<p>Northern France inherited the Paris region, Rouen, Orléans, Angers, Poitiers, Dijon, Nancy, Laon, and Châlons-sur-Marne. Its mass manufacturing entered German procurement, credit, railway, gauge, and technical-standard systems while retaining French brands that helped the continuing <em>État français</em> claim legitimacy.</p>"},
      {id:"south",title:"Occitania and the Latin technical economy",html:"<p>Occitania inherited Toulouse, Bordeaux, Limoges, Clermont-Ferrand, Lyon, Marseille, and Montpellier. It lacked northern scale but possessed aerospace concentration, tyres, trucks, chemicals, hydroelectric engineering, pharmaceuticals, control systems, and Mediterranean and Atlantic ports.</p>"},
      {id:"claims",title:"Ownership did not follow so neatly",html:"<p>Cross-border shares, bonds, pension funds, trademarks, dealer networks, patents, and research records entered custodianship or clearing accounts. The <a href='cross-border-french-industrial-claims.html'>claims regime</a> separated title from control and made almost every major settlement politically sensitive.</p>"},
      {id:"standards",title:"One workshop culture becomes several standards systems",html:"<p>Northern firms increasingly built to German and Einheitspakt specifications. Occitan firms adopted Latin procurement and accounting conventions. Export versions, adapters, translated drawings, and licensed components preserved trade but raised costs and encouraged technically distinct product families.</p>"},
      {id:"labor",title:"Engineers, workers, and archives",html:"<p>People did not divide as cleanly as buildings. Firms petitioned to move engineers, families crossed before controls hardened, and both governments classified drawings, prototypes, tool inventories, and personnel files as strategic assets. Later defections and technical exchanges remained intelligence matters.</p>"},
      {id:"legacy",title:"Legacy",html:"<p>By 1985 neither successor state possessed the complete prewar French industrial system. Northern France had greater mass and continental access; Occitania held disproportionate strength in high-value integration. Their dependence upon one another survived beneath tariff schedules, political ritual, and incompatible national histories.</p>"}
    ],
    related:[{href:"four-frances.html",kicker:"Political settlement",label:"The Four Frances"},{href:"cross-border-french-industrial-claims.html",kicker:"Legal aftermath",label:"Cross-border Industrial Claims"},{href:"automobile-industry-northern-france.html",kicker:"Northern system",label:"Northern Automobile Industry"},{href:"motor-industry-occitania.html",kicker:"Occitan system",label:"Motor Industry of Occitania"},{href:"french-aerospace-industrial-partition.html",kicker:"Strategic sector",label:"Aerospace Industrial Partition"},{href:"latin-bloc.html",kicker:"Southern market",label:"Latin Bloc"}],
    facts:[["Date","1947"],["Immediate rule","Control followed the physical plant"],["Northern center","Paris and the Seine industrial region"],["Occitan centers","Toulouse, Bordeaux, Lyon, Clermont-Ferrand"],["Northern alignment","Einheitspakt standards and finance"],["Occitan alignment","Latin technical and procurement system"],["Most disputed assets","Shares, brands, patents, debts, and pensions"],["Final claims settlement","Incomplete and sector-specific"]]
  }),

  "cross-border-french-industrial-claims":frenchIndustryArticle({
    title:"Cross-border French industrial claims",eyebrow:"1947–1985 · ownership without possession after partition",infoboxKicker:"Commercial and diplomatic claims regime",
    lead:"<strong>Cross-border French industrial claims</strong> are the shareholdings, debts, trademarks, patents, licenses, pensions, and contracts left on the wrong side of the 1947 French frontier. The regime allowed a company or family to remain an owner in law while a hostile successor state controlled the actual plant. It became a permanent subject of bilateral bargaining among Paris, Toulouse, Berlin, Rome, Barcelona, banks, and corporate boards.",
    canon:"The conflict between physical possession and wider corporate identity is established as the governing industrial problem. Custodianship, blocked accounts, licensing, compensation, and plant-for-share exchanges are working mechanisms. No universal treaty or complete firm-by-firm settlement is fixed.",
    sections:[
      {id:"problem",title:"Title and control separate",html:"<p>Territorial authorities controlled gates, payrolls, utilities, police, and production. Foreign shareholders could file claims and sometimes receive income, but they could not appoint unrestricted managers or remove machines across the frontier.</p>"},
      {id:"custody",title:"Custodianship and local boards",html:"<p>Both states used custodians, compulsory local directors, and strategic-industry commissioners. These arrangements were presented as temporary protection of national assets even when they became the normal form of governance.</p>"},
      {id:"accounts",title:"Blocked dividends and clearing",html:"<p>Dividends, royalties, debt service, and pension payments accumulated in controlled accounts. Bilateral clearing converted some balances into approved imports, reinvestment, or compensation rather than freely transferable currency.</p>"},
      {id:"brands",title:"Brands and dealer networks",html:"<p>A brand could remain recognizable on both sides while factories produced divergent models. Trademark licenses defined territory, exports, advertising language, and the right to claim continuity with the pre-partition firm.</p>"},
      {id:"patents",title:"Patents and technical records",html:"<p>Patent ownership mattered less than possession of drawings, test data, jigs, and experienced staff. Governments restricted technical transfer while allowing selective licenses needed to keep essential vehicles, tyres, medicines, and machinery in production.</p>"},
      {id:"labor",title:"Pensions and professional standing",html:"<p>Partitioned firms owed pensions to workers living abroad and depended upon credentials issued by rival successor institutions. Negotiations over actuarial reserves and professional recognition often outlasted disputes over machinery.</p>"},
      {id:"settlements",title:"Sector-by-sector settlements",html:"<p>Governments used compensation bonds, reciprocal releases, minority share recognition, long leases, and plant-for-claim exchanges. Strategic aerospace and armaments cases remained more restrictive than tyres, pharmaceuticals, or ordinary consumer goods.</p>"},
      {id:"diplomacy",title:"A barometer of Franco-Occitan relations",html:"<p>Every thaw reopened claims conferences, and every political crisis produced new controls. By 1985 the system was stable enough for commerce but too incomplete to answer the larger question of whether the firms remained French, northern, Occitan, or multinational.</p>"}
    ],
    related:[{href:"french-industrial-partition-1947.html",kicker:"Origin",label:"French Industrial Partition"},{href:"citroen.html",kicker:"Leading ownership dispute",label:"Citroën"},{href:"rhone-poulenc.html",kicker:"Dual regional firm",label:"Rhône-Poulenc"},{href:"michelin.html",kicker:"Occitan claimant",label:"Michelin"},{href:"northern-france.html",kicker:"Northern jurisdiction",label:"Northern France"},{href:"occitania.html",kicker:"Southern jurisdiction",label:"Occitania"}],
    facts:[["Origin","French partition of 1947"],["Core distinction","Legal title versus physical control"],["Plant authority","Territorial successor government"],["Common mechanism","Custodianship and compulsory local boards"],["Payment mechanism","Blocked accounts and bilateral clearing"],["Strategic exclusions","Aerospace, armaments, and sensitive records"],["Principal examples","Citroën and Rhône-Poulenc"],["Status in 1985","Stable but incomplete"]]
  }),

  "automobile-industry-northern-france":frenchIndustryArticle({
    title:"Automobile industry of Northern France",eyebrow:"Billancourt, Javel, Nanterre, Poissy, and Sochaux",infoboxKicker:"Northern French industrial sector",
    lead:"The <strong>automobile industry of Northern France</strong> is the largest surviving concentration of French passenger-car production after partition. Renault at Billancourt, Citroën at Javel, Simca at Nanterre, Ford's works at Poissy, Panhard on avenue d'Ivry, and Peugeot at Sochaux give Paris a collection of rival marques rather than one consolidated national combine.",
    canon:"The inherited plant geography and Northern France's integration into the German continental economy are fixed. Continued separate identities for Renault, Citroën, Peugeot, Simca, and Panhard are working canon adopted to avoid importing later real-world mergers. Exact output, model chronology, ownership percentages, and plant expansions remain open.",
    sections:[
      {id:"inheritance",title:"A dense inherited cluster",html:"<p>The Seine region combined assembly plants, foundries, body makers, machine tools, engineering schools, roads, railways, suppliers, and the country's largest consumer market. Sochaux added a family-owned eastern complex close to German industry.</p>"},
      {id:"reconstruction",title:"Postwar reconstruction",html:"<p>Material shortages and damaged transport initially favored rugged small cars, trucks, vans, tractors, and fleet repair. The northern state allocated steel and credit while allowing several brands to compete for civilian and official orders.</p>"},
      {id:"firms",title:"Five principal marques",html:"<p><a href='renault.html'>Renault</a> became the state-supervised mass producer. <a href='citroen.html'>Citroën</a> carried the sharpest ownership dispute. <a href='peugeot.html'>Peugeot</a> retained family and provincial identity, <a href='simca.html'>Simca</a> mediated Italian technology, and <a href='panhard.html'>Panhard</a> specialized in light engineering and military vehicles.</p>"},
      {id:"poissy",title:"Poissy and foreign capital",html:"<p>Ford's Poissy works remained an American-owned industrial enclave subject to northern licensing and German continental conditions. Any later transfer to Simca required a negotiated transaction and is not assumed from real history.</p>"},
      {id:"standards",title:"Einheitspakt standards",html:"<p>Fasteners, electrical systems, fuels, tyres, freight dimensions, military specifications, and supplier certification moved toward continental norms. French styling and marque identity survived because they carried commercial and political value.</p>"},
      {id:"market",title:"Protected market and controlled exports",html:"<p>Northern buyers formed the home market, while Germany and its associated states offered scale under quotas and procurement rules. Exports to the Latin system required adapters, licenses, or distinct production runs.</p>"},
      {id:"labor",title:"Labor and corporative supervision",html:"<p>Works councils, state labor offices, party organizations, and company welfare structures managed a skilled workforce with strong prewar collective memory. Strikes and plant politics were treated as both economic and security questions.</p>"},
      {id:"1985",title:"The sector by 1985",html:"<p>Northern France possessed a broad vehicle industry but not a fully sovereign one. German standards, finance, and market access shaped design choices, while the survival of multiple French badges helped Paris present dependency as continuity.</p>"}
    ],
    related:[{href:"renault.html",kicker:"Billancourt",label:"Renault"},{href:"citroen.html",kicker:"Javel",label:"Citroën"},{href:"peugeot.html",kicker:"Sochaux",label:"Peugeot"},{href:"simca.html",kicker:"Nanterre",label:"Simca"},{href:"panhard.html",kicker:"Paris",label:"Panhard"},{href:"motor-industry-occitania.html",kicker:"Southern counterpart",label:"Motor Industry of Occitania"}],
    facts:[["State","Northern France"],["Principal region","Paris and the Seine valley"],["Eastern center","Sochaux"],["Principal firms","Renault, Citroën, Peugeot, Simca, Panhard"],["Foreign plant","Ford SAF at Poissy"],["Technical alignment","Einheitspakt standards"],["Political value","French industrial continuity"],["1985 structure","Protected multi-marque sector"]]
  }),

  "motor-industry-occitania":frenchIndustryArticle({
    title:"Motor industry of Occitania",eyebrow:"Tyres, trucks, buses, components, and military mobility",infoboxKicker:"Occitan industrial sector",
    lead:"The <strong>motor industry of Occitania</strong> is a specialized vehicle and component system centered on Michelin in Clermont-Ferrand and Berliet in the Lyon–Vénissieux corridor. It cannot match the passenger-car volume inherited by Northern France, but it supplies tyres, heavy trucks, buses, military transports, engines, controls, and engineering services to the Latin market.",
    canon:"Michelin and Berliet as core Occitan firms, a smaller passenger-car base, and Latin-oriented technical integration are established working canon. Exact national champions beyond these firms, model lists, production totals, and ownership shares remain open.",
    sections:[
      {id:"geography",title:"Clermont and Lyon",html:"<p>Clermont-Ferrand contributes rubber chemistry, tyres, testing, maps, and road knowledge. Lyon and Vénissieux contribute heavy vehicle assembly, machine tools, metallurgy, electrical supply, and access to the Rhône transport corridor.</p>"},
      {id:"specialization",title:"Specialization rather than passenger-car scale",html:"<p>Occitan policy favors trucks, buses, utility vehicles, ambulances, tractors, military mobility, and high-value components. Imported or licensed passenger cars fill segments that northern plants once supplied domestically.</p>"},
      {id:"michelin",title:"Michelin as system company",html:"<p><a href='michelin.html'>Michelin</a> supplies tyres and materials while road testing, guides, and technical standards make it an information company as well as a manufacturer. Its blocked Citroën interests keep it tied to the northern market.</p>"},
      {id:"berliet",title:"Berliet and heavy transport",html:"<p><a href='berliet.html'>Berliet</a> provides the state's most visible vehicle marque. Civilian freight, municipal buses, colonial and export trucks, fire engines, and military chassis give the firm strategic status.</p>"},
      {id:"suppliers",title:"A component economy",html:"<p>Rhône chemicals, Alpine electrical equipment, Toulouse controls, Limoges ceramics, and Mediterranean importers support engines, brakes, instruments, insulation, paints, fuels, and special-purpose bodies.</p>"},
      {id:"latin",title:"Latin standardization",html:"<p>Italy, Spain, Portugal, and associated markets offer scale but also expose local firms to stronger vehicle producers. Occitania competes through ruggedness, fleet packages, technical service, and specialized military or municipal designs.</p>"},
      {id:"exports",title:"Africa and the Mediterranean",html:"<p>Trucks, buses, tyres, and repair kits suit long-distance routes and uneven infrastructure in Latin-aligned African territories and Mediterranean partners. Export finance often joins a vehicle sale to road, depot, or training contracts.</p>"},
      {id:"limits",title:"Strategic strengths and limits",html:"<p>The sector makes Occitania difficult to isolate and supports its armed forces, but dependence upon imported fuel, some machine tools, and outside passenger-car designs prevents claims of complete automotive independence.</p>"}
    ],
    related:[{href:"michelin.html",kicker:"Clermont-Ferrand",label:"Michelin"},{href:"berliet.html",kicker:"Lyon and Vénissieux",label:"Berliet"},{href:"clermont-ferrand.html",kicker:"Tyre center",label:"Clermont-Ferrand"},{href:"lyon.html",kicker:"Heavy industry",label:"Lyon"},{href:"automobile-industry-northern-france.html",kicker:"Northern counterpart",label:"Northern Automobile Industry"},{href:"occitania.html",kicker:"Country",label:"Occitania"}],
    facts:[["State","Occitania"],["Principal centers","Clermont-Ferrand and Lyon–Vénissieux"],["Leading firms","Michelin and Berliet"],["Primary products","Tyres, trucks, buses, components"],["Passenger-car scale","Limited"],["Technical alignment","Latin system"],["Export emphasis","Mediterranean and African fleet markets"],["Strategic role","Military and civil mobility"]]
  }),

  "french-aerospace-industrial-partition":frenchIndustryArticle({
    title:"French aerospace industrial partition",eyebrow:"1947 · state combines, design bureaus, and airfields divided",infoboxKicker:"Strategic industrial partition",
    lead:"The <strong>French aerospace industrial partition</strong> divided a sector that had already been reorganized into regional national companies in 1936–37 and again under wartime administration. Toulouse, Bordeaux, Marignane, Cannes, and other southern works gave Occitania a powerful production and design inheritance, while Paris, Normandy, Picardy, and central plants left Northern France with engines, laboratories, component firms, and its own airframe capacity.",
    canon:"Occitania's disproportionate aerospace strength, the Toulouse–Bordeaux evacuation legacy, and preservation of the Dassault, Dewoitine, Latécoère, Breguet, SNCASO, and SNCASE traditions are established. This article treats those names as plant, design, and institutional lineages unless a surviving legal company is separately fixed. Exact 1947 allocations and later merger names remain open.",
    sections:[
      {id:"nationalization",title:"The 1936–37 regional combines",html:"<p>Prewar nationalization grouped factories into northern, central, western, south-western, south-eastern, and Midi companies. Those administrative boundaries never erased the older brands, designers, specialist shops, or geographically scattered plants beneath them.</p>"},
      {id:"wartime",title:"Wartime concentration and movement",html:"<p>Occupation, dispersal, collaboration, damage, and relocation moved personnel and records. Toulouse absorbed the former SNCAM organization into SNCASE, while Bordeaux-Mérignac and nearby works preserved the south-western airframe tradition.</p>"},
      {id:"frontier",title:"Partition by plant",html:"<p>The 1947 settlement placed Toulouse, Bordeaux, Marseille, and Lyon inside Occitania. Paris, Normandy, Picardy, and the Loire approaches fell under northern or neighboring jurisdictions. Corporate headquarters and combined accounts therefore no longer matched factory geography.</p>"},
      {id:"occitan",title:"Occitan concentration",html:"<p>Toulouse became the coordinating center for airframes, electronics, guidance, testing, and systems integration. Bordeaux preserved combat-aircraft and Atlantic aviation work, while Marseille and the south-east supplied helicopters, maritime aircraft, engines, and Mediterranean access.</p>"},
      {id:"northern",title:"Northern residual strength",html:"<p>Northern France retained major design offices, engine and equipment firms, wind-tunnel and research assets, skilled Paris-region subcontractors, and northern airframe plants. German procurement gave those institutions scale but narrowed independent program choice.</p>"},
      {id:"lineages",title:"Names, firms, and lineages",html:"<p>Dassault, Dewoitine, Latécoère, Breguet, SNCASO, and SNCASE could denote a designer's school, a plant ancestry, a brand, or a state successor. The wiki distinguishes those meanings rather than assuming the later real-world corporate genealogy.</p>"},
      {id:"latin",title:"Latin integration",html:"<p>Occitania became the Latin system's specialist in interfaces among aircraft, avionics, missiles, sensors, computing, and space hardware. Italy and Spain provided larger procurement bases while Toulouse bargained for program leadership through technical indispensability.</p>"},
      {id:"legacy",title:"Long-term legacy",html:"<p>The partition made aerospace the strongest argument for Occitania's viability and one of Northern France's deepest grievances. Cooperation remained possible through licensed components, but complete reintegration would have required political decisions neither state could treat as merely commercial.</p>"}
    ],
    related:[{href:"sncam-dewoitine.html",kicker:"Toulouse lineage",label:"SNCAM and the Dewoitine Tradition"},{href:"occitan-combat-aircraft-lineage.html",kicker:"Program history",label:"Occitan Combat-Aircraft Lineage"},{href:"toulouse.html",kicker:"Aerospace capital",label:"Toulouse"},{href:"bordeaux.html",kicker:"Combat-aircraft center",label:"Bordeaux"},{href:"occitania.html",kicker:"Principal inheritor",label:"Occitania"},{href:"northern-france.html",kicker:"Northern inheritor",label:"Northern France"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/SNCAM",label:"Wikipedia — SNCAM (pre-divergence institutional baseline)"},{href:"https://en.wikipedia.org/wiki/SNCASE",label:"Wikipedia — SNCASE (pre-divergence institutional baseline)"},{href:"https://en.wikipedia.org/wiki/SNCASO",label:"Wikipedia — SNCASO (pre-divergence institutional baseline)"}],
    facts:[["Prewar reorganization","Nationalization of 1936–1937"],["Partition date","1947"],["Occitan center","Toulouse"],["Occitan secondary centers","Bordeaux and the Mediterranean south-east"],["Northern strengths","Engines, research, components, and northern airframe plants"],["Principal Occitan role","Systems integration"],["Institutional problem","Brands and combines crossed the frontier"],["Later corporate genealogy","Partly open"]]
  }),

  "renault":frenchIndustryArticle({
    title:"Renault",eyebrow:"Billancourt mass producer and northern state champion",category:"Companies of Northern France",infoboxKicker:"Automobile manufacturer",
    lead:"<strong>Renault</strong> is a Northern French automobile, truck, tractor, engine, and industrial-equipment manufacturer centered at Boulogne-Billancourt. Founded by Louis, Marcel, and Fernand Renault in 1899, the firm emerged from the war under close state control and became the principal mass producer of the continuing <em>État français</em>.",
    canon:"The 1899 foundation, Billancourt geography, and prewar product breadth are historical baseline. Renault's survival as a distinct, state-supervised northern champion is working canon. The legal form and rationale of postwar state control deliberately differ from the Free French nationalization and remain open in detail.",
    sections:[
      {id:"foundation",title:"Foundation and growth",html:"<p>The Renault brothers established the company in 1899 after Louis Renault's early light-car experiments. Production expanded at Boulogne-Billancourt into one of France's largest integrated motor works.</p>"},
      {id:"war",title:"War production and political exposure",html:"<p>Vehicles, engines, repair, and industrial capacity made Billancourt strategically indispensable and politically compromised. Wartime production bound managers and workers to occupation authorities in ways the victorious continental order judged differently from the historical French Republic.</p>"},
      {id:"control",title:"State-supervised reconstruction",html:"<p>Paris placed the firm under strategic custody to preserve employment, transport, and military capacity. Whether the resulting organization is formally a nationalized <em>régie</em>, a mixed corporation, or a sequence of emergency administrations remains open.</p>"},
      {id:"products",title:"Cars, trucks, tractors, and machinery",html:"<p>Small family cars carried the marque into mass consumption, while vans, lorries, tractors, engines, rail equipment, and defense contracts made Renault broader than an automobile company.</p>"},
      {id:"continental",title:"Continental standards and markets",html:"<p>German specifications shaped components, fuel systems, electrical equipment, military contracts, and exports. Renault retained French model names and styling where national legitimacy and consumer loyalty made them valuable.</p>"},
      {id:"labor",title:"Billancourt labor society",html:"<p>The works concentrated skilled labor, migrants, technical cadres, housing, welfare, surveillance, and suppressed collective traditions. The factory became both a model workplace and a potential political danger to the northern regime.</p>"},
      {id:"competition",title:"A champion among surviving rivals",html:"<p>State preference did not eliminate Citroën, Peugeot, Simca, or Panhard. Rival marques provided specialist capacity and prevented Renault's industrial administration from becoming the entire national motor sector.</p>"},
      {id:"legacy",title:"By 1985",html:"<p>Renault embodied Northern France's central paradox: a famous French badge, a workforce and plant rooted in Paris, and a product system inseparable from German continental power.</p>"}
    ],
    related:[{href:"automobile-industry-northern-france.html",kicker:"National sector",label:"Northern Automobile Industry"},{href:"paris.html",kicker:"Metropolitan setting",label:"Paris"},{href:"citroen.html",kicker:"Mass-market rival",label:"Citroën"},{href:"peugeot.html",kicker:"Eastern rival",label:"Peugeot"},{href:"simca.html",kicker:"Nanterre rival",label:"Simca"},{href:"northern-france.html",kicker:"Country",label:"Northern France"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Renault",label:"Wikipedia — Renault (pre-divergence company baseline)"}],
    facts:[["Founded","25 February 1899"],["Founders","Louis, Marcel, and Fernand Renault"],["Principal works","Boulogne-Billancourt"],["State","Northern France"],["Products","Cars, trucks, tractors, engines, and industrial equipment"],["Postwar status","State-supervised strategic company"],["Technical market","Einheitspakt"],["Exact legal form","Open"]]
  }),

  "citroen":frenchIndustryArticle({
    title:"Citroën",eyebrow:"Javel manufacturer under a disputed Michelin claim",category:"Companies of divided France",infoboxKicker:"Automobile manufacturer and cross-border claim",
    lead:"<strong>Citroën</strong> is the most politically important divided corporation created by the French partition. Its Quai de Javel factory, Paris administration, workers, and principal market fell under Northern France, while Michelin—the controlling shareholder since the 1934 rescue—was centered in Occitan Clermont-Ferrand. The marque therefore continued under northern physical control and an unresolved southern ownership claim.",
    canon:"The Javel geography, 1919 first car, 1934 Michelin rescue, and prewar design programs are historical baseline. Northern operating control, continuing Michelin claim, and separate marque identity are working canon. Exact share recognition, management, model dates, and compensation remain open.",
    sections:[
      {id:"foundation",title:"André Citroën and Javel",html:"<p>André Citroën converted his wartime Paris plant to automobile production, delivering the marque's first car in 1919. Large-scale methods, advertising, dealer service, and technical novelty made Citroën a national institution.</p>"},
      {id:"michelin",title:"Michelin rescue",html:"<p>Bankruptcy in 1934 brought the company under Michelin control. Pierre Michelin and then Pierre-Jules Boulanger reorganized the firm, joining a Paris automobile manufacturer to a Clermont-Ferrand tyre group.</p>"},
      {id:"partition",title:"The 1947 corporate fracture",html:"<p>Northern authorities controlled Javel and the dealer organization within their territory. Occitan law continued to recognize Michelin's financial claim, creating a company whose factory, brand, and capital no longer belonged to one jurisdiction.</p>"},
      {id:"custody",title:"Northern custodianship",html:"<p>A compulsory northern board kept production, employment, procurement, and sales operating. Michelin received only the rights allowed through blocked accounts, technical licenses, and intermittent claims agreements.</p>"},
      {id:"design",title:"Economy cars and technical distinction",html:"<p>Prewar work on an austere rural car and the firm's hydropneumatic and front-wheel-drive traditions remained valuable. This setting does not assume the historical 2CV or DS launch dates unchanged, but preserves their underlying design schools as contested corporate assets.</p>"},
      {id:"tyres",title:"Tyres, patents, and supply",html:"<p>Michelin tyres and research could reach Javel through licensed trade even when ownership rights were frozen. Northern authorities cultivated alternative suppliers to reduce the political leverage carried by every shipment.</p>"},
      {id:"identity",title:"Who owns the double chevron?",html:"<p>Paris presented Citroën as proof of French industrial continuity. Toulouse and Clermont-Ferrand argued that appropriation of the operating company could not extinguish its lawful parent. Advertising and export badges became statements of sovereignty.</p>"},
      {id:"1985",title:"An unresolved success",html:"<p>By 1985 Citroën survived as a recognizable northern manufacturer whose prosperity did not settle the underlying claim. Its endurance demonstrated that a divided company could become permanent without becoming legally simple.</p>"}
    ],
    related:[{href:"michelin.html",kicker:"Controlling shareholder in 1934",label:"Michelin"},{href:"cross-border-french-industrial-claims.html",kicker:"Claims regime",label:"Cross-border Industrial Claims"},{href:"automobile-industry-northern-france.html",kicker:"Operating sector",label:"Northern Automobile Industry"},{href:"paris.html",kicker:"Javel works",label:"Paris"},{href:"renault.html",kicker:"Principal rival",label:"Renault"},{href:"occitania.html",kicker:"Shareholder jurisdiction",label:"Occitania"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Citro%C3%ABn",label:"Wikipedia — Citroën (pre-divergence company baseline)"}],
    facts:[["First automobile","1919"],["Principal works","Quai de Javel, Paris"],["Controlling shareholder since 1934","Michelin"],["Operating jurisdiction after 1947","Northern France"],["Claimant jurisdiction","Occitania"],["Governance","Compulsory northern custodianship"],["Principal dispute","Shares, brand, patents, and dividends"],["1985 status","Operating, claim unresolved"]]
  }),

  "peugeot":frenchIndustryArticle({
    title:"Peugeot",eyebrow:"Sochaux family manufacturer on the continental frontier",category:"Companies of Northern France",infoboxKicker:"Automobile manufacturer",
    lead:"<strong>Peugeot</strong> is a Northern French family automobile and engineering company centered on Sochaux and the Montbéliard country. Its eastern factory complex fell within the Dijon-oriented portion of Northern France rather than German-annexed Alsace–Lorraine, leaving the marque formally French but physically close to the industrial center of the Einheitspakt.",
    canon:"The Peugeot family's industrial history, Sochaux concentration, 202 restart, and 203 program are historical baseline through the divergence. Northern jurisdiction and continued separate family-company identity are working canon. Later real-world mergers are not assumed.",
    sections:[
      {id:"origins",title:"Family industrial origins",html:"<p>The Peugeot enterprise grew from nineteenth-century metalworking in the Franche-Comté border country into bicycles, tools, and automobiles. Provincial family ownership distinguished it from the Paris-centered mass producers.</p>"},
      {id:"sochaux",title:"The Sochaux complex",html:"<p>Automobile production concentrated at Sochaux from the interwar period, supported by Montbéliard engineering, rail access, supplier towns, and a workforce organized around the company.</p>"},
      {id:"war",title:"War and restart",html:"<p>Occupation demands, material removal, damage, and labor disruption reduced production. The durable 202 and the developing 203 supplied a plausible reconstruction base, though their exact post-1947 chronology diverges from real history.</p>"},
      {id:"frontier",title:"A frontier manufacturer",html:"<p>Sochaux's proximity to German-annexed territory made customs, security, rail routing, and technical standards immediate factory concerns. German suppliers and markets were close enough to be useful and powerful enough to threaten autonomy.</p>"},
      {id:"family",title:"Family control under supervision",html:"<p>The regime treated Peugeot's family identity as a stabilizing provincial asset while placing defense contracts, labor policy, foreign licensing, and capital movement under strategic review.</p>"},
      {id:"products",title:"Conservative engineering and broad service",html:"<p>Peugeot competed through robust family cars, light commercial vehicles, bicycles, tools, engines, and repairability rather than the theatrical state symbolism associated with Renault or Citroën.</p>"},
      {id:"market",title:"Continental market",html:"<p>Einheitspakt access rewarded common components and certified suppliers. The firm protected its own badge and dealer network because provincial loyalty and export reputation were its strongest bargaining assets.</p>"},
      {id:"independence",title:"A separate lineage",html:"<p>The later real-world PSA sequence does not occur here, and Peugeot remains one of several northern marques. Cooperation with Citroën or other firms can occur through licenses and joint components while each company preserves its corporate independence.</p>"}
    ],
    related:[{href:"automobile-industry-northern-france.html",kicker:"National sector",label:"Northern Automobile Industry"},{href:"renault.html",kicker:"State rival",label:"Renault"},{href:"citroen.html",kicker:"Paris rival",label:"Citroën"},{href:"simca.html",kicker:"Continental rival",label:"Simca"},{href:"french-industrial-partition-1947.html",kicker:"Political settlement",label:"French Industrial Partition"},{href:"northern-france.html",kicker:"Country",label:"Northern France"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Peugeot",label:"Wikipedia — Peugeot (pre-divergence company baseline)"}],
    facts:[["Industrial roots","Peugeot family metalworking"],["Principal works","Sochaux"],["Region","Montbéliard and Franche-Comté"],["State after 1947","Northern France"],["Postwar base","202 and 203 lineages"],["Ownership","Family company under strategic supervision"],["Technical alignment","Einheitspakt"],["Later real-world mergers","Not assumed"]]
  }),

  "simca":frenchIndustryArticle({
    title:"Simca",eyebrow:"Nanterre manufacturer between northern control and Fiat lineage",category:"Companies of Northern France",infoboxKicker:"Automobile manufacturer",
    lead:"<strong>Simca</strong> is a Northern French automobile manufacturer created from Fiat's French operations and centered at Nanterre. After 1947 it occupied an awkward position between northern territorial control, German continental standards, and the technical and financial claims of Fiat inside the Latin system.",
    canon:"Simca's Fiat origin and Nanterre geography are historical baseline. Its survival as a locally chartered northern company using negotiated Fiat licenses is working canon. Historical acquisition of Ford SAF at Poissy and later Chrysler ownership are not automatically imported.",
    sections:[
      {id:"fiat",title:"Fiat's French operation",html:"<p>Henri Théodore Pigozzi developed the French Fiat business into Simca, assembling licensed designs and creating a distinct national marque. Nanterre supplied the company with a modern Paris-region production base.</p>"},
      {id:"war",title:"Wartime survival",html:"<p>Its Italian association protected Simca from some political pressures while exposing it to others. The firm entered the settlement as a French operating company whose technical ancestry belonged to a victorious but separate Latin power.</p>"},
      {id:"charter",title:"Northern charter and local control",html:"<p>Paris required local directors, domestic reinvestment, and strategic licensing. Fiat retained technical and financial claims only within agreements acceptable to Northern France and its German sponsor.</p>"},
      {id:"hinge",title:"A German–Latin industrial hinge",html:"<p>Simca translated Fiat practice into a factory working under northern rules and continental standards. That made it commercially useful during détente and politically suspect during bloc crises.</p>"},
      {id:"models",title:"Small cars and licensed engineering",html:"<p>Compact passenger cars and light commercial vehicles suited reconstruction and urban markets. Over time local engineering distinguished northern Simca products from their Italian relatives even where engines or tooling shared an ancestry.</p>"},
      {id:"poissy",title:"Ford SAF and Poissy",html:"<p>The nearby Ford SAF plant at Poissy remained a separate American-owned concern unless an in-setting sale is fixed. The historical 1954 transfer to Simca is therefore a possibility, not a default event.</p>"},
      {id:"competition",title:"Competition and identity",html:"<p>Simca competed beneath Renault's state preference and against Citroën and Peugeot's stronger French legitimacy. Its adaptable licensing culture and export contacts compensated for political ambiguity.</p>"},
      {id:"legacy",title:"By 1985",html:"<p>The firm survives as a northern marque with Latin ancestry rather than a simple foreign subsidiary. Its boardroom arrangements are among the clearest indicators of relations between Berlin's and Rome's economic systems.</p>"}
    ],
    related:[{href:"automobile-industry-northern-france.html",kicker:"National sector",label:"Northern Automobile Industry"},{href:"cross-border-french-industrial-claims.html",kicker:"Legal framework",label:"Cross-border Industrial Claims"},{href:"renault.html",kicker:"Mass-market rival",label:"Renault"},{href:"citroen.html",kicker:"Paris rival",label:"Citroën"},{href:"italy.html",kicker:"Fiat home system",label:"Italy"},{href:"paris.html",kicker:"Nanterre region",label:"Paris"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Simca",label:"Wikipedia — Simca (pre-divergence company baseline)"},{href:"https://en.wikipedia.org/wiki/Ford_SAF",label:"Wikipedia — Ford SAF and Poissy (historical baseline)"}],
    facts:[["Origin","French Fiat operations"],["Key organizer","Henri Théodore Pigozzi"],["Principal works","Nanterre"],["State after 1947","Northern France"],["Technical ancestry","Fiat"],["Postwar form","Locally chartered company with negotiated licenses"],["Poissy acquisition","Not fixed"],["Later Chrysler ownership","Not assumed"]]
  }),

  "michelin":frenchIndustryArticle({
    title:"Michelin",eyebrow:"Clermont-Ferrand tyre group and Occitan national champion",category:"Companies of Occitania",infoboxKicker:"Tyre, rubber, and mobility company",
    lead:"<strong>Michelin</strong> is an Occitan tyre, rubber, mapping, and mobility company headquartered in Clermont-Ferrand. Founded in its modern form by Édouard and André Michelin in 1889, it became one of Occitania's indispensable national champions after partition. Its prewar control of Citroën also made it the largest southern claimant against a major northern operating company.",
    canon:"The 1889 foundation, Clermont-Ferrand headquarters, tyre innovations, guides, and control of Citroën from 1934 are historical baseline. Michelin as an Occitan champion, developer of radial tyres, and claimant to Citroën is established working canon. Plantation supply, exact claim percentages, and settlement terms remain open.",
    sections:[
      {id:"foundation",title:"Clermont-Ferrand origins",html:"<p>Édouard and André Michelin developed the family enterprise into a modern tyre company in 1889. Removable pneumatic tyres, road testing, technical service, and a factory-centered urban economy made Clermont-Ferrand inseparable from the marque.</p>"},
      {id:"information",title:"Maps, guides, and road knowledge",html:"<p>Maps and guides encouraged motoring while collecting practical knowledge about roads, distances, service points, and travel. The company therefore combined materials science with an information system long before electronic navigation.</p>"},
      {id:"citroen",title:"The Citroën investment",html:"<p>Michelin rescued Citroën in 1934 and obtained control of the Paris automaker. Partition left the parent in Occitania and the operating factory in Northern France, converting an equity investment into a diplomatic dispute.</p>"},
      {id:"radial",title:"Radial tyre technology",html:"<p>The radial tyre developed around 1946 offered durability, efficiency, and handling advantages. Occitan policy treated the patents, machinery, test practice, and skilled workforce behind it as strategic national assets.</p>"},
      {id:"supplies",title:"Rubber and overseas supply",html:"<p>Japanese control in Indochina and the division of world trade forced diversification of natural-rubber purchases, synthetic-rubber research, recycling, and stockpiles. Supply contracts linked the company to several blocs despite national protection.</p>"},
      {id:"latin",title:"A Latin system company",html:"<p>Michelin supplied Italian, Spanish, Portuguese, Occitan, and associated fleets while defending its designs against compulsory standardization. Its tyres became an export whose performance gave a small state technical leverage.</p>"},
      {id:"society",title:"Company and city",html:"<p>Housing, welfare, laboratories, training, sports, and paternal discipline made Michelin a civic institution in Clermont-Ferrand. The Occitan government depended upon the group while refusing to let it become a private state.</p>"},
      {id:"1985",title:"By 1985",html:"<p>Michelin stands at the center of Occitan motor industry and cross-border finance. It supplies northern markets it does not politically trust and claims a carmaker it cannot directly govern.</p>"}
    ],
    related:[{href:"citroen.html",kicker:"Contested subsidiary",label:"Citroën"},{href:"clermont-ferrand.html",kicker:"Company city",label:"Clermont-Ferrand"},{href:"motor-industry-occitania.html",kicker:"National sector",label:"Motor Industry of Occitania"},{href:"cross-border-french-industrial-claims.html",kicker:"Claims regime",label:"Cross-border Industrial Claims"},{href:"berliet.html",kicker:"Occitan vehicle partner",label:"Berliet"},{href:"occitania.html",kicker:"Country",label:"Occitania"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Michelin",label:"Wikipedia — Michelin (pre-divergence company baseline)"}],
    facts:[["Modern foundation","1889"],["Founders","Édouard and André Michelin"],["Headquarters","Clermont-Ferrand"],["State after 1947","Occitania"],["Principal products","Tyres and rubber systems"],["Major technical asset","Radial tyre"],["Contested holding","Citroën"],["Political position","Occitan national champion"]]
  }),

  "berliet":frenchIndustryArticle({
    title:"Berliet",eyebrow:"Lyon–Vénissieux truck and heavy-vehicle champion",category:"Companies of Occitania",infoboxKicker:"Truck and bus manufacturer",
    lead:"<strong>Berliet</strong> is an Occitan truck, bus, military-vehicle, and industrial-engine manufacturer based in the Lyon–Vénissieux area. Founded by Marius Berliet in 1899, the company gives Occitania a complete heavy-vehicle institution even though most French passenger-car production lies north of the frontier.",
    canon:"The 1899 foundation, Lyon and Vénissieux geography, and prewar automobile, truck, bus, and military production are historical baseline. Continued independent existence as an Occitan strategic manufacturer is working canon. The historical postwar sequestration and later Renault absorption do not occur in the same form.",
    sections:[
      {id:"foundation",title:"Marius Berliet",html:"<p>Marius Berliet established the marque in 1899 after early workshop production around Lyon. Heavy vehicles, engines, and a reputation for durable mechanical engineering became increasingly central to the company.</p>"},
      {id:"venissieux",title:"Vénissieux industrial complex",html:"<p>Land acquired during the First World War supported a large integrated works at Vénissieux and Saint-Priest. The site linked assembly, engines, foundry work, testing, worker housing, and the Rhône transport economy.</p>"},
      {id:"war",title:"War, continuity, and altered justice",html:"<p>Wartime production exposed the firm to collaboration charges and labor conflict. Because Occitania partly broke with Vichy continuity while emerging under Axis victory, the historical French sequestration could not simply repeat; state supervision rested on new sovereign and strategic grounds.</p>"},
      {id:"products",title:"Trucks and buses",html:"<p>Road tractors, rigid trucks, municipal buses, fire engines, construction chassis, and special vehicles made Berliet essential to freight, cities, mines, ports, and public works.</p>"},
      {id:"military",title:"Military mobility",html:"<p>Military trucks, command vehicles, recovery equipment, and armored or specialized chassis tied Berliet to the Occitan defense establishment and Latin procurement programs.</p>"},
      {id:"exports",title:"Mediterranean and African markets",html:"<p>Rugged designs, depot packages, driver training, and spare-parts systems supported exports to Latin-aligned African territories and Mediterranean partners where road conditions rewarded serviceability.</p>"},
      {id:"ownership",title:"Family, state, and corporative labor",html:"<p>Family management survived within strategic oversight, credit controls, labor representation, and procurement planning. The exact balance among family shares, public capital, and worker bodies remains open.</p>"},
      {id:"independence",title:"An independent Occitan lineage",html:"<p>Berliet is not absorbed into Renault along the later real-world path. It remains the heavy-vehicle counterweight to Michelin and one of Lyon's strongest claims to national industrial leadership.</p>"}
    ],
    related:[{href:"motor-industry-occitania.html",kicker:"National sector",label:"Motor Industry of Occitania"},{href:"lyon.html",kicker:"Home metropolis",label:"Lyon"},{href:"michelin.html",kicker:"Tyre supplier",label:"Michelin"},{href:"rhone-poulenc.html",kicker:"Rhône industrial peer",label:"Rhône-Poulenc"},{href:"occitan-army.html",kicker:"Military customer",label:"Occitan Army"},{href:"occitania.html",kicker:"Country",label:"Occitania"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Berliet",label:"Wikipedia — Berliet (pre-divergence company baseline)"}],
    facts:[["Founded","1899"],["Founder","Marius Berliet"],["Principal complex","Vénissieux–Saint-Priest"],["Metropolitan center","Lyon"],["State after 1947","Occitania"],["Principal products","Trucks, buses, engines, and military vehicles"],["Postwar status","Strategic family company under supervision"],["Historical Renault absorption","Does not automatically occur"]]
  }),

  "panhard":frenchIndustryArticle({
    title:"Panhard",eyebrow:"Paris pioneer of light vehicles and armored reconnaissance",category:"Companies of Northern France",infoboxKicker:"Automobile and military-vehicle manufacturer",
    lead:"<strong>Panhard</strong>, historically Panhard & Levassor, is a Northern French automobile and military-vehicle manufacturer based on avenue d'Ivry in Paris. One of the oldest French motor marques, it survives the partition as a smaller engineering house specializing in light cars, efficient powertrains, armored reconnaissance, and unusual vehicle layouts.",
    canon:"The avenue d'Ivry origin, early Daimler licenses, pioneering automobile status, and military-vehicle work are historical baseline. Survival as an independent northern specialist is working canon. Later real-world Citroën ownership and termination of civilian production are not assumed.",
    sections:[
      {id:"origins",title:"Panhard and Levassor",html:"<p>René Panhard and Émile Levassor transformed an older machine business into an automobile maker at avenue d'Ivry. Daimler engine licenses and the firm's first cars helped establish the layout of the early motor industry.</p>"},
      {id:"prestige",title:"The senior marque",html:"<p>Racing, luxury cars, engineering innovation, and an origin in the first years of motoring gave Panhard prestige out of proportion to its later production volume.</p>"},
      {id:"war",title:"Military and industrial continuity",html:"<p>Armored cars, engines, and specialist vehicles preserved the company when mass passenger-car competition favored larger firms. Paris treated its design staff and military experience as assets worth keeping separate.</p>"},
      {id:"civilian",title:"Light civilian vehicles",html:"<p>Economical engines, light construction, aerodynamic bodies, and unconventional solutions supported a niche range for professional and urban buyers. Exact model names and dates remain open after divergence.</p>"},
      {id:"armored",title:"Reconnaissance and security vehicles",html:"<p>Fast wheeled reconnaissance cars, internal-security vehicles, liaison machines, and specialist chassis connected Panhard to northern and Einheitspakt defense procurement without turning it into a heavy-armored producer.</p>"},
      {id:"independence",title:"Independence among larger rivals",html:"<p>The state preserved Panhard as a competitive design bureau and niche producer. It shared components and contracts with larger firms without following the historical path into Citroën ownership.</p>"},
      {id:"paris",title:"A Paris industrial institution",html:"<p>The avenue d'Ivry works tied the marque to the capital's skilled metalworking neighborhoods. Urban redevelopment, labor supervision, and the value of central land repeatedly tested its independence.</p>"},
      {id:"legacy",title:"By 1985",html:"<p>Panhard's production is smaller than Renault's or Peugeot's, but its survival gives Northern France an adaptable military-vehicle specialist and a living claim to the earliest French motor tradition.</p>"}
    ],
    related:[{href:"automobile-industry-northern-france.html",kicker:"National sector",label:"Northern Automobile Industry"},{href:"paris.html",kicker:"Home city",label:"Paris"},{href:"renault.html",kicker:"Mass producer",label:"Renault"},{href:"citroen.html",kicker:"Historical later owner not assumed",label:"Citroën"},{href:"peugeot.html",kicker:"Independent rival",label:"Peugeot"},{href:"northern-france.html",kicker:"Country",label:"Northern France"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Panhard",label:"Wikipedia — Panhard (pre-divergence company baseline)"},{href:"https://en.wikipedia.org/wiki/Ren%C3%A9_Panhard",label:"Wikipedia — René Panhard and the avenue d'Ivry works"}],
    facts:[["Historical name","Panhard & Levassor"],["Founders","René Panhard and Émile Levassor"],["Principal works","Avenue d'Ivry, Paris"],["State after 1947","Northern France"],["Civilian specialization","Light and technically unusual cars"],["Military specialization","Wheeled reconnaissance and security vehicles"],["Postwar form","Independent specialist"],["Historical Citroën absorption","Not assumed"]]
  }),

  "sncam-dewoitine":frenchIndustryArticle({
    title:"SNCAM and the Dewoitine tradition",eyebrow:"Toulouse aircraft lineage from private firm to Occitan state industry",category:"Aerospace industry of Occitania",infoboxKicker:"Aircraft manufacturing lineage",
    lead:"<strong>SNCAM and the Dewoitine tradition</strong> describe the Toulouse aircraft lineage that began with Émile Dewoitine's company, entered the state-owned Société nationale des constructions aéronautiques du Midi in 1937, and was absorbed into SNCASE around 1940–41. After the French partition the name SNCAM denoted an industrial ancestry rather than necessarily a surviving legal corporation, but its factories, staff, drawings, and D.520 experience became part of Occitania's aerospace claim.",
    canon:"Dewoitine's Toulouse origin, 1937 nationalization into SNCAM, the D.520, and absorption into SNCASE are historical baseline. The 1947 transfer of the Toulouse institutional lineage into Occitan control is established working canon. The final state-company name, Émile Dewoitine's personal postwar role, and exact successor genealogy remain open.",
    sections:[
      {id:"dewoitine",title:"Émile Dewoitine in Toulouse",html:"<p>Dewoitine established his aircraft company in Toulouse in 1920. The city provided workshops, an aviation labor pool, airfields, and a southern setting that became central to the firm's identity.</p>"},
      {id:"nationalization",title:"Creation of SNCAM",html:"<p>The 1937 nationalization placed the former Dewoitine enterprise inside the state-owned Société nationale des constructions aéronautiques du Midi. The new combine preserved much of the Toulouse plant and design tradition beneath public ownership.</p>"},
      {id:"d520",title:"The D.520 legacy",html:"<p>The Dewoitine D.520 gave the lineage its most important wartime combat-aircraft reference. Its aerodynamics, production lessons, tooling, and engineering culture mattered after the specific fighter became obsolete.</p>"},
      {id:"aircraft",title:"List of Aircraft",html:"<p>The internal designation is Dewoitine's company design number. The official designation gives the full public aircraft title. The list records principal pre-divergence types inherited by the Toulouse lineage rather than assigning names to later Occitan projects.</p><div class='table-wrap'><table class='wiki-table'><thead><tr><th>Internal designation</th><th>Official designation</th></tr></thead><tbody><tr><td>D.1</td><td>Dewoitine D.1<sup class='canon-note' data-provenance='p'>[p]</sup></td></tr><tr><td>D.27</td><td>Dewoitine D.27<sup class='canon-note' data-provenance='p'>[p]</sup></td></tr><tr><td>D.338</td><td>Dewoitine D.338<sup class='canon-note' data-provenance='p'>[p]</sup></td></tr><tr><td>D.500</td><td>Dewoitine D.500<sup class='canon-note' data-provenance='p'>[p]</sup></td></tr><tr><td>D.510</td><td>Dewoitine D.510<sup class='canon-note' data-provenance='p'>[p]</sup></td></tr><tr><td>D.520</td><td>Dewoitine D.520<sup class='canon-note' data-provenance='p'>[p]</sup></td></tr><tr><td>D.551</td><td>Dewoitine D.551<sup class='canon-note' data-provenance='p'>[p]</sup></td></tr></tbody></table></div>"},
      {id:"sncase",title:"Absorption into SNCASE",html:"<p>Wartime reorganization absorbed SNCAM into SNCASE around 1940–41 and moved engineering functions toward the former Toulouse organization. Legal disappearance did not erase the local workforce or technical memory.</p>"},
      {id:"partition",title:"Occitan inheritance in 1947",html:"<p>The Toulouse sites, records physically present there, and resident engineers entered Occitan control. Claims from northern ministries or the wider state combine could not overcome possession of the working industrial community.</p>"},
      {id:"successors",title:"From company to lineage",html:"<p>Later Occitan organizations could use new names while tracing their legitimacy to Dewoitine and SNCAM. The distinction prevents anachronistically treating a defunct legal company as though it continued unchanged.</p>"},
      {id:"programs",title:"Combat aircraft and systems integration",html:"<p>The lineage contributed airframe design, flight test, production engineering, and military culture to the <a href='occitan-combat-aircraft-lineage.html'>Occitan combat-aircraft system</a>. Electronics, guidance, and Latin collaborative programs eventually mattered more than a single inherited marque.</p>"},
      {id:"memory",title:"Industrial memory",html:"<p>Occitan public history presents Dewoitine and SNCAM as proof that Toulouse was an aircraft capital before independence. Northern critics answer that the plants were built by a national French state whose property was divided by force.</p>"}
    ],
    related:[{href:"french-aerospace-industrial-partition.html",kicker:"Sectoral setting",label:"Aerospace Industrial Partition"},{href:"occitan-combat-aircraft-lineage.html",kicker:"Postwar programs",label:"Occitan Combat-Aircraft Lineage"},{href:"toulouse.html",kicker:"Home city",label:"Toulouse"},{href:"occitania.html",kicker:"Successor state",label:"Occitania"},{href:"northern-france.html",kicker:"Competing claimant",label:"Northern France"},{href:"latin-military-aviation.html",kicker:"Regional system",label:"Latin Military Aviation"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Dewoitine",label:"Wikipedia — Dewoitine (pre-divergence company baseline)"},{href:"https://en.wikipedia.org/wiki/SNCAM",label:"Wikipedia — SNCAM (pre-divergence institutional baseline)"},{href:"https://en.wikipedia.org/wiki/SNCASE",label:"Wikipedia — SNCASE (wartime organizational baseline)"}],
    facts:[["Private predecessor","Dewoitine"],["Dewoitine founded","1920"],["State company","SNCAM"],["SNCAM created","1937"],["Principal city","Toulouse"],["Major aircraft","Dewoitine D.520"],["Absorbed by","SNCASE, c. 1940–1941"],["Post-1947 meaning","Occitan plant and design lineage"]]
  }),

  "rhone-poulenc":frenchIndustryArticle({
    title:"Rhône-Poulenc",eyebrow:"Lyon–Paris chemical and pharmaceutical group divided by the frontier",category:"Companies of divided France",infoboxKicker:"Chemical and pharmaceutical group",
    lead:"<strong>Rhône-Poulenc</strong> is the divided chemical and pharmaceutical group created in 1928 by the union of Lyon's Société des usines chimiques du Rhône and the Paris-based Poulenc Frères establishment. Its very name joined the two industrial regions later separated in 1947. Occitania inherited the Rhône production and research center; Northern France inherited important Paris offices, laboratories, sales networks, and facilities.",
    canon:"The 1928 Lyon–Paris merger and the group's prewar chemical and pharmaceutical identity are historical baseline. A dual operating structure under cross-border claims is working canon. Exact factory allocations, brand licenses, board structure, and whether the legal parent ultimately divides remain open.",
    sections:[
      {id:"formation",title:"A Lyon–Paris merger",html:"<p>Rhône-Poulenc formed in 1928 by combining the Société des usines chimiques du Rhône with Poulenc Frères. The merger connected Rhône chemical production and research to Parisian pharmaceutical, commercial, and scientific networks.</p>"},
      {id:"products",title:"Chemicals and pharmaceuticals",html:"<p>Industrial chemicals, fibres, intermediates, dyes, agricultural products, medicines, and laboratory research placed the group inside civilian health, textiles, agriculture, and strategic manufacturing at once.</p>"},
      {id:"partition",title:"The corporate map breaks in 1947",html:"<p>Lyon and the Rhône corridor entered Occitania while Paris entered Northern France. Plants, patents, scientists, stocks, sales offices, and liabilities did not align neatly enough for either state to claim a complete company.</p>"},
      {id:"dual",title:"Dual operating companies",html:"<p>Each jurisdiction authorized a local operating company under custodianship and strategic regulation. Shared brands and selected licenses continued where medical necessity or export value outweighed political objection.</p>"},
      {id:"research",title:"Research and records",html:"<p>Laboratory notebooks, strain collections, pilot plants, process knowledge, and specialist teams proved more important than formal patent certificates. Movement of scientists and samples became a regulated security matter.</p>"},
      {id:"health",title:"Medicines across a hostile frontier",html:"<p>Public-health demand made complete embargo impractical. Governments negotiated essential-drug supply, quality recognition, and reciprocal licensing even while reserving military chemistry and advanced processes.</p>"},
      {id:"batch-release",title:"Batch release across the frontier",html:"<!-- altwwii-writer-block:start id=wb-v-20260816-r5v9d writer=v kind=extrapolation created=2026-08-16T14:16:43-06:00 --><p>A medicine shipment had to connect the approved product to a particular batch, manufacturer, strength and formulation, package, storage history, and accompanying test record. The receiving side compared those particulars with the license it recognized, inspected the consignment, and could hold samples or stock for further checking before distribution. A shared brand did not make batches from the Lyon and northern organizations interchangeable when their legal manufacturers or formulations differed.</p><p>Urgent public-health demand could justify limited or provisional release, while a damaged seal, broken storage condition, incomplete record, or failed comparison could leave needed stock in quarantine. A later defect report had to identify the affected batch and reach hospitals, pharmacies, distributors, and the other operating company quickly enough to stop further use. Commercial secrecy and suspicion of industrial espionage limited how much process information either side wished to disclose, making quality recognition a continuing transaction rather than a one-time political settlement.</p><!-- altwwii-writer-block:end -->"},
      {id:"blocs",title:"Two standards systems",html:"<p>The northern organization served German and Einheitspakt specifications. The Lyon organization entered Latin regulation, finance, and procurement. Export products sometimes shared a badge while differing in formulation, packaging, and legal manufacturer.</p>"},
      {id:"identity",title:"One name, several institutions",html:"<p>By 1985 Rhône-Poulenc is simultaneously a remembered French group, an Occitan industrial champion, and a northern operating company. Whether that arrangement represents survival or partition depends upon which balance sheet and flag is being used.</p>"}
    ],
    related:[{href:"cross-border-french-industrial-claims.html",kicker:"Legal framework",label:"Cross-border Industrial Claims"},{href:"lyon.html",kicker:"Southern center",label:"Lyon"},{href:"paris.html",kicker:"Northern center",label:"Paris"},{href:"french-industrial-partition-1947.html",kicker:"Origin",label:"French Industrial Partition"},{href:"occitania.html",kicker:"Rhône jurisdiction",label:"Occitania"},{href:"northern-france.html",kicker:"Paris jurisdiction",label:"Northern France"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Rh%C3%B4ne-Poulenc",label:"Wikipedia — Rhône-Poulenc (pre-divergence company baseline)"}],
    facts:[["Founded","1928"],["Predecessors","Société des usines chimiques du Rhône and Poulenc Frères"],["Southern center","Lyon and the Rhône corridor"],["Northern center","Paris"],["Principal sectors","Chemicals and pharmaceuticals"],["Post-1947 form","Dual operating structure"],["Shared assets","Brands, patents, research, and claims"],["Final legal partition","Open"]]
  })
});

function enrichFrenchIndustryArticle(key,section,related){
  const article=window.deepArticles[key];
  if(!article)return;
  article.sections=article.sections||[];
  if(!article.sections.some(item=>item.id===section.id))article.sections.push(section);
  article.related=article.related||[];
  related.forEach(item=>{if(!article.related.some(existing=>existing.href===item.href))article.related.push(item);});
}

enrichFrenchIndustryArticle("northern-france",{id:"industrial-partition",title:"Industry after the French partition",html:"<p>Paris inherited the densest surviving French automobile cluster, while Sochaux, Normandy, and eastern engineering entered a German-centered continental system. <a href='renault.html'>Renault</a>, <a href='citroen.html'>Citroën</a>, <a href='peugeot.html'>Peugeot</a>, <a href='simca.html'>Simca</a>, and <a href='panhard.html'>Panhard</a> remained recognizable firms, but German standards, strategic supervision, and <a href='cross-border-french-industrial-claims.html'>cross-border ownership claims</a> constrained their independence.</p>"},[{href:"french-industrial-partition-1947.html",kicker:"Economic settlement",label:"French Industrial Partition"},{href:"automobile-industry-northern-france.html",kicker:"Principal sector",label:"Northern Automobile Industry"}]);
enrichFrenchIndustryArticle("occitania",{id:"industrial-inheritance",title:"The southern industrial inheritance",html:"<p>Occitania inherited a smaller but unusually valuable system centered on Toulouse and Bordeaux aerospace, <a href='michelin.html'>Michelin</a> at Clermont-Ferrand, <a href='berliet.html'>Berliet</a> and <a href='rhone-poulenc.html'>Rhône-Poulenc</a> around Lyon, and Rhône–Alpine electrical and chemical industry. This geography made high-value integration, rather than mass manufacturing, a foundation of sovereignty.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},[{href:"french-industrial-partition-1947.html",kicker:"Economic settlement",label:"French Industrial Partition"},{href:"motor-industry-occitania.html",kicker:"Vehicle sector",label:"Motor Industry of Occitania"},{href:"french-aerospace-industrial-partition.html",kicker:"Strategic sector",label:"Aerospace Industrial Partition"}]);
enrichFrenchIndustryArticle("four-frances",{id:"industrial-map",title:"Factories and firms across the four Frances",html:"<p>The political frontier also cut corporate France. Immediate factory control followed territory, while shares, patents, brands, pensions, and sales networks produced decades of <a href='cross-border-french-industrial-claims.html'>cross-border claims</a>. The resulting <a href='french-industrial-partition-1947.html'>industrial partition</a> made reunification an argument about property and standards as well as identity.</p>"},[{href:"french-industrial-partition-1947.html",kicker:"Economic consequence",label:"French Industrial Partition"},{href:"cross-border-french-industrial-claims.html",kicker:"Unresolved property",label:"Cross-border Industrial Claims"}]);
enrichFrenchIndustryArticle("paris",{id:"motor-industry",title:"The Paris motor belt",html:"<p>Billancourt, Javel, Nanterre, Poissy, and avenue d'Ivry placed <a href='renault.html'>Renault</a>, <a href='citroen.html'>Citroën</a>, <a href='simca.html'>Simca</a>, Ford SAF, and <a href='panhard.html'>Panhard</a> inside the capital's industrial region. Their survival made Paris the center of the <a href='automobile-industry-northern-france.html'>northern automobile industry</a> and a principal arena of foreign ownership disputes.</p>"},[{href:"automobile-industry-northern-france.html",kicker:"Metropolitan sector",label:"Northern Automobile Industry"},{href:"renault.html",kicker:"Billancourt",label:"Renault"},{href:"citroen.html",kicker:"Javel",label:"Citroën"}]);
enrichFrenchIndustryArticle("toulouse",{id:"dewoitine-inheritance",title:"SNCAM and the Dewoitine inheritance",html:"<p>The former Dewoitine works and <a href='sncam-dewoitine.html'>SNCAM institutional lineage</a> gave Toulouse a pre-independence aircraft identity. Their incorporation into the Occitan state made the city both an aerospace capital and a disputed inheritor of French nationalized industry.</p>"},[{href:"sncam-dewoitine.html",kicker:"Aircraft ancestry",label:"SNCAM and the Dewoitine Tradition"},{href:"french-aerospace-industrial-partition.html",kicker:"Sectoral settlement",label:"Aerospace Industrial Partition"}]);
enrichFrenchIndustryArticle("bordeaux",{id:"aerospace-inheritance",title:"Bordeaux and the south-west aircraft works",html:"<p>Bordeaux-Mérignac and related south-western plants carried the SNCASO and combat-aircraft inheritance into Occitania. With Toulouse they formed the core of the <a href='french-aerospace-industrial-partition.html'>southern aerospace system</a>, though company identities and state claims remained contested.</p>"},[{href:"french-aerospace-industrial-partition.html",kicker:"Industrial inheritance",label:"Aerospace Industrial Partition"},{href:"occitan-combat-aircraft-lineage.html",kicker:"Program lineage",label:"Occitan Combat-Aircraft Lineage"}]);
enrichFrenchIndustryArticle("lyon",{id:"berliet-rhone-poulenc",title:"Berliet and Rhône-Poulenc",html:"<p><a href='berliet.html'>Berliet</a> made the Lyon–Vénissieux corridor Occitania's heavy-vehicle center. <a href='rhone-poulenc.html'>Rhône-Poulenc</a> joined local chemicals and pharmaceuticals to a disputed Paris half, making Lyon both a national industrial capital and a claimant in the divided French economy.</p>"},[{href:"berliet.html",kicker:"Heavy vehicles",label:"Berliet"},{href:"rhone-poulenc.html",kicker:"Chemicals and medicines",label:"Rhône-Poulenc"}]);
enrichFrenchIndustryArticle("clermont-ferrand",{id:"michelin-company-city",title:"Michelin and the company city",html:"<p><a href='michelin.html'>Michelin</a> made Clermont-Ferrand the tyre, rubber, testing, and road-information center of Occitania. Its 1934 control of Paris-based <a href='citroen.html'>Citroën</a> also placed the city at the heart of the largest post-partition corporate claim.</p>"},[{href:"michelin.html",kicker:"National champion",label:"Michelin"},{href:"citroen.html",kicker:"Contested holding",label:"Citroën"}]);
